test("override can represent an unrepresentable type", () => {
  const override = (ctx: any) => {
    if (ctx.zodSchema._zod.def.type === "date") {
      ctx.jsonSchema.type = "string";
      ctx.jsonSchema.format = "date-time";
    }
  };
  expect(z.toJSONSchema(z.object({ when: z.date() }), { override }).properties).toEqual({
    when: { type: "string", format: "date-time" },
  });
  expect(() => z.toJSONSchema(z.object({ when: z.date(), id: z.bigint() }), { override })).toThrow(
    "BigInt cannot be represented in JSON Schema"
  );
  expect(() =>
    z.toJSONSchema(z.date().describe("a"), {
      override: (ctx) => {
        ctx.jsonSchema.description = "b";
      },
    })
  ).toThrow("Date cannot be represented in JSON Schema");
});
